package com.procurement.approvalstage.mapper; import com.procurement.approvalrule.entity.ApprovalRule; import com.procurement.approvalstage.dto.request.*; import com.procurement.approvalstage.dto.response.*; import com.procurement.approvalstage.entity.*; import com.procurement.role.entity.Role; import org.springframework.stereotype.Component;
@Component public class ApprovalStageMapper{public ApprovalStage toEntity(ApprovalStageRequest r,ApprovalRule a,Role role){var e=new ApprovalStage();update(e,r,a,role);return e;}public void update(ApprovalStage e,ApprovalStageRequest r,ApprovalRule a,Role role){e.setApprovalRule(a);e.setStageNumber(r.stageNumber());e.setStageName(r.stageName());e.setApproverRole(role);e.setMinimumApprovers(r.minimumApprovers());e.setMandatoryApproval(r.mandatoryApproval()==null||r.mandatoryApproval());e.setSequence(r.sequence());e.setActive(r.active()==null||r.active());}public ApprovalStageResponse toResponse(ApprovalStage e){return new ApprovalStageResponse(e.getId(),e.getApprovalRule().getId(),e.getApprovalRule().getRuleCode(),e.getStageNumber(),e.getStageName(),e.getApproverRole().getId(),e.getApproverRole().getRoleName(),e.getMinimumApprovers(),e.getMandatoryApproval(),e.getSequence(),e.getActive(),e.getCreatedAt(),e.getUpdatedAt());}}
